def find_solutions(limit):
    solutions = []
    for x in range(1, limit + 1):
        for y in range(x, limit + 1):
            # x^2*y^2*z^2 - z^3 = x^3 + y^3
            # z^2 (x^2*y^2 - z) = x^3 + y^3
            # Let k = x^2*y^2 - z. Since x^3 + y^3 > 0 and z > 0, k must be > 0.
            # z = x^2*y^2 - k
            # (x^2*y^2 - k)^2 * k = x^3 + y^3
            # We can iterate over small k.
            # As k increases, (x^2*y^2 - k)^2 * k will eventually increase or decrease.
            # But k is a divisor of x^3 + y^3.
            val = x**3 + y**3
            for k in range(1, val + 1):
                if val % k == 0:
                    # z^2 = val / k
                    z2 = val // k
                    z = int(z2**0.5)
                    if z * z == z2:
                        # Check if z = x^2*y^2 - k
                        if z == x**2 * y**2 - k:
                            if x <= y <= z:
                                solutions.append((x, y, z))
    return solutions

print(find_solutions(100))

def find_solutions_refined(x_limit, y_limit):
    solutions = []
    for x in range(1, x_limit + 1):
        for y in range(x, y_limit + 1):
            # z must satisfy z^2(x^2*y^2 - z) = x^3 + y^3
            # And z >= y.
            # Since z^2 <= x^3 + y^3, we have z <= sqrt(x^3 + y^3).
            # So we only check z in range [y, floor(sqrt(x^3 + y^3))].
            import math
            z_max = int(math.isqrt(x**3 + y**3))
            for z in range(y, z_max + 1):
                if x**3 + y**3 + z**3 == x**2 * y**2 * z**2:
                    solutions.append((x, y, z))
    return solutions

print(find_solutions_refined(100, 100))
